<?php
namespace Ishep\Http;
final class Request { private array $attributes=[]; public function __construct(public string $method,public string $path,public array $query,public array $input,public array $server){} public static function capture():self{$path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';$base=rtrim(str_replace('\\','/',dirname($_SERVER['SCRIPT_NAME']??'')),'/');if($base&&$base!=='/'&&str_starts_with($path,$base))$path=substr($path,strlen($base))?:'/';return new self(strtoupper($_SERVER['REQUEST_METHOD']??'GET'),'/'.ltrim($path,'/'),$_GET,$_POST,$_SERVER);} public function set(string $k,mixed $v):void{$this->attributes[$k]=$v;} public function get(string $k,mixed $d=null):mixed{return $this->attributes[$k]??$d;} public function ip():string{return (string)($this->server['REMOTE_ADDR']??'unknown');} }
